          buf = buf.slice(i + 2);
          if (chunk.startsWith("data: ")) {
            try {
              events.push(JSON.parse(chunk.slice(6)));
            } catch {}
          }
        }
      });
      resolve({ status: 200, events, req });
    });
    req.on("error", () => {});
    setTimeout(() => resolve({ status: -1, events, req }), 8000);
  });
}

